var WorldMatrixMath=class{static combine(child,parent){if(!parent)return{...child};let px=parent.x||0,py=parent.y||0,pRot=(parent.rotation||0)*(Math.PI/180),pScaleX=parent.scaleX??1,pScaleY=parent.scaleY??1,cx=child.x||0,cy=child.y||0,scaledX=cx*pScaleX,scaledY=cy*pScaleY,rotatedX=scaledX*Math.cos(pRot)-scaledY*Math.sin(pRot),rotatedY=scaledX*Math.sin(pRot)+scaledY*Math.cos(pRot);return{x:px+rotatedX,y:py+rotatedY,rotation:(child.rotation||0)+(parent.rotation||0),scaleX:(child.scaleX??1)*pScaleX,scaleY:(child.scaleY??1)*pScaleY}}};var HierarchyResolver=class{static resolve(entity,state,depth=0){if(!entity)return{x:0,y:0,rotation:0,scaleX:1,scaleY:1};if(depth>10)return console.warn('B"H - Hierarchy Paradox Detected! Infinity loop severed.'),this._getBaseTransform(entity);let localTransform=this._getBaseTransform(entity);if(!entity.parentId&&!entity.mountedTo)return localTransform;let targetId=entity.parentId||entity.mountedTo,parentEntity=this._findEntityById(targetId,state);if(!parentEntity)return localTransform;let parentWorldTransform=this.resolve(parentEntity,state,depth+1);return entity.mountedTo&&(localTransform.y+=entity.mountOffsetY||-60,localTransform.x+=entity.mountOffsetX||0),WorldMatrixMath.combine(localTransform,parentWorldTransform)}static _getBaseTransform(entity){return entity.position?{x:entity.position.x||0,y:entity.position.y||0,rotation:entity.rotation||0,scaleX:entity.position.scale??1,scaleY:Math.abs(entity.position.scale??1)}:{x:entity.x||0,y:entity.y||0,rotation:entity.rotation||0,scaleX:Math.abs(entity.scaleX??entity.scale??1),scaleY:Math.abs(entity.scaleY??entity.scale??1)}}static _findEntityById(id,state){let chars=state.get("characters")||{};if(chars[id])return chars[id];let scene=state.get("scene")||{},domains=["props","foliage","buildings"];for(let domain of domains)if(scene[domain]){let found=scene[domain].find(e=>e.id===id);if(found)return found}return null}};export{HierarchyResolver};
